reference_solution.python:
class Solution:
    def removeElement(self, nums: List[int], val: int) -> int:
        i = 0
        for x in nums:
            if x != val:
                nums[i] = x
                i += 1
        return i

reference_solution.javascript:
function removeElement(nums, val) {
    let i = 0;
    for (const x of nums) {
        if (x !== val) {
            nums[i] = x;
            i++;
        }
    }
    return i;
}
